import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
  UserId,
  IsoTimestamp,
} from "./common";
import type { IssueStatus, IssuePriority } from "./issue";
import type { Role } from "./member";
import type { PlanId, LimitedResource } from "./billing";
import type { FeatureFlagKey } from "./feature-flag";

/** Fields present on every event payload; the bus stamps them on `emit`. */
export interface EventEnvelope {
  readonly orgId: OrgId;
  readonly actorId: UserId | null;
  readonly occurredAt: IsoTimestamp;
}

/**
 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 * only way to introduce one — services, jobs and the webhook dispatcher all
 * derive their handler signatures from it.
 */
export interface TaskflowEventMap {
  "project.created": EventEnvelope & {
    projectId: ProjectId;
    name: string;
    slug: string;
  };
  "project.archived": EventEnvelope & {
    projectId: ProjectId;
    issuesArchived: number;
  };
  "project.restored": EventEnvelope & { projectId: ProjectId };
  "issue.created": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    title: string;
    assigneeId: UserId | null;
    priority: IssuePriority;
  };
  "issue.updated": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    changedFields: readonly string[];
  };
  "issue.status_changed": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    from: IssueStatus;
    to: IssueStatus;
  };
  "issue.assigned": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    previousAssigneeId: UserId | null;
    assigneeId: UserId;
  };
  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
  "issue.overdue": EventEnvelope & {
    issueId: IssueId;
    projectId: ProjectId;
    dueAt: IsoTimestamp;
    assigneeId: UserId | null;
  };
  "comment.created": EventEnvelope & {
    commentId: CommentId;
    issueId: IssueId;
    mentionedUserIds: readonly UserId[];
  };
  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
  "member.invited": EventEnvelope & { email: string; role: Role };
  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
  "member.role_changed": EventEnvelope & {
    memberId: MemberId;
    from: Role;
    to: Role;
  };
  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
  "billing.limit_exceeded": EventEnvelope & {
    resource: LimitedResource;
    limit: number;
    used: number;
  };
  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
  "search.reindex_requested": EventEnvelope & {
    subjectKind: "issue" | "comment" | "project";
    subjectId: string;
  };
  "webhook.delivery_requested": EventEnvelope & {
    eventType: string;
    payload: Readonly<Record<string, unknown>>;
  };
}

export type TaskflowEventType = keyof TaskflowEventMap;

export type TaskflowEventPayload<K extends TaskflowEventType> =
  TaskflowEventMap[K];

/** A handler registered with `subscribe()`. May be async; errors are isolated. */
export type EventHandler<K extends TaskflowEventType> = (
  payload: TaskflowEventPayload<K>,
) => void | Promise<void>;

/** Returned by `subscribe()`; calling it removes the handler. */
export type Unsubscribe = () => void;
/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
import type { LimitedResource, PlanId } from "@/types/billing";
import type { FeatureFlagKey } from "@/types/feature-flag";

/**
 * The one place plan quotas are declared.
 *
 * `BillingService`, the invite flow, the project-create action, the webhook
 * settings page, the usage meter component and the seat-limit job all read
 * their numbers from here via `getPlanLimits()`. Adding a field to
 * `PlanLimits` therefore ripples into every one of those call sites — that
 * ripple is intentional and is what keeps the quotas honest.
 */
export interface PlanLimits {
  readonly plan: PlanId;
  readonly seats: number;
  readonly projects: number;
  readonly issuesPerProject: number;
  readonly storageMb: number;
  readonly apiRequestsPerHour: number;
  readonly webhooks: number;
  readonly retentionDays: number;
  readonly includedFlags: readonly FeatureFlagKey[];
  readonly priceCentsPerSeatMonthly: number;
}

/** `Infinity` is the sanctioned representation of "no limit". */
export const UNLIMITED = Number.POSITIVE_INFINITY;

export const PLAN_LIMITS: Readonly<Record<PlanId, PlanLimits>> = {
  free: {
    plan: "free",
    seats: 3,
    projects: 2,
    issuesPerProject: 100,
    storageMb: 100,
    apiRequestsPerHour: 100,
    webhooks: 0,
    retentionDays: 30,
    includedFlags: ["command_palette"],
    priceCentsPerSeatMonthly: 0,
  },
  starter: {
    plan: "starter",
    seats: 10,
    projects: 10,
    issuesPerProject: 1_000,
    storageMb: 2_000,
    apiRequestsPerHour: 1_000,
    webhooks: 2,
    retentionDays: 90,
    includedFlags: ["command_palette", "kanban_board", "csv_export"],
    priceCentsPerSeatMonthly: 900,
  },
  growth: {
    plan: "growth",
    seats: 50,
    projects: 100,
    issuesPerProject: 10_000,
    storageMb: 20_000,
    apiRequestsPerHour: 10_000,
    webhooks: 10,
    retentionDays: 365,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
    ],
    priceCentsPerSeatMonthly: 1_900,
  },
  enterprise: {
    plan: "enterprise",
    seats: UNLIMITED,
    projects: UNLIMITED,
    issuesPerProject: UNLIMITED,
    storageMb: 500_000,
    apiRequestsPerHour: 100_000,
    webhooks: UNLIMITED,
    retentionDays: 2_555,
    includedFlags: [
      "command_palette",
      "kanban_board",
      "csv_export",
      "activity_feed",
      "digest_email",
      "webhooks",
      "issue_templates",
      "advanced_search",
      "public_projects",
      "ai_issue_summary",
    ],
    priceCentsPerSeatMonthly: 3_900,
  },
};

/** Plans ordered cheapest → richest; used for "at least this plan" checks. */
export const PLAN_ORDER: readonly PlanId[] = [
  "free",
  "starter",
