s=s.replace('''/**
 * Board drag-and-drop.''','''/**
 * Brings an archived issue back out of the trash. After tenant scope, lookup
 * and the `issue:archive` permission (author and assignee escalate, as for
 * archiving), the restore is refused unless the issue is archived, still
 * inside the plan's `retentionDays` window, in a live project that has room
 * under the per-project quota. A refusal changes and publishes nothing.
 * The issue keeps its number; `issue.restored` lets the usage counter, the
 * search index and the audit log follow.
 */
export async function restoreIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));

  if (!isArchived(issue)) {
    throw new RestoreRefusedError(
      "not_archived",
      `Issue ${issue.id} is not archived.`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
