/** The slice of an expired issue the retention sweep needs to plan a purge. */
export interface ExpiredIssueRef {
  readonly id: IssueId;
  readonly projectId: ProjectId;
  readonly number: number;
}

/**
 * Up to `limit` archived issues of the org whose `archived_at` is at or before
 * `cutoff`, across every project. The caller purges what it gets and asks
 * again, so no cursor is needed.
 */
export async function listExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
  limit: number,
): Promise<readonly ExpiredIssueRef[]> {
  const rows = getDb()
    .select({
      id: issues.id,
      projectId: issues.projectId,
      number: issues.number,
    })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .orderBy(issues.id)
    .limit(Math.max(1, limit))
    .all();

  return rows.map((row) => ({
    id: row.id as IssueId,
    projectId: row.projectId as ProjectId,
    number: row.number,
  }));
}

export interface PurgeIssuesResult {
  /** Issue rows actually removed. */
  readonly issues: number;
  /** Whole megabytes the removed attachments were counted for, each rounded up. */
  readonly storageMb: number;
}

/**
 * Permanently removes archived issues with their label links, comments and
 * attachments, in one transaction. Live issues in `issueIds` are left alone.
 * Each project's highest-ever issue number is recorded first, so the numbers
 * of purged issues are never handed out again. Search documents and the
 * storage counter are the caller's to settle; the result carries the
 * megabytes to give back.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgeIssuesResult> {
  if (issueIds.length === 0) return { issues: 0, storageMb: 0 };

  return getDb().transaction((tx) => {
    const doomed = tx
      .select({
        id: issues.id,
        projectId: issues.projectId,
        number: issues.number,
      })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          inArray(issues.id, [...issueIds]),
          isNotNull(issues.archivedAt),
        ),
      )
      .all();
    if (doomed.length === 0) return { issues: 0, storageMb: 0 };

    const ids = doomed.map((row) => row.id);

    const sizes = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .all();
    const storageMb = sizes.reduce(
      (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
      0,
    );

    const highestByProject = new Map<string, number>();
    for (const row of doomed) {
      highestByProject.set(
        row.projectId,
        Math.max(highestByProject.get(row.projectId) ?? 0, row.number),
      );
    }
    for (const [projectId, highestNumber] of highestByProject) {
      tx.insert(issueNumberCounters)
        .values({ projectId, orgId, highestNumber })
        .onConflictDoUpdate({
          target: issueNumberCounters.projectId,
          set: {
            highestNumber: sql`max(${issueNumberCounters.highestNumber}, ${highestNumber})`,
          },
        })
        .run();
    }

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          inArray(issueLabels.issueId, ids),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(
          orgPredicate(comments.orgId, orgId),
          inArray(comments.issueId, ids),
        ),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          inArray(attachments.issueId, ids),
        ),
      )
      .run();
    tx.delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, ids)))
      .run();

    return { issues: doomed.length, storageMb };
  });
}
