/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, retentionCutoff
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { IsoTimestamp, OrgId } from "@/types/common";

const ORG_BATCH = 25;
/** Issues purged per transaction; keeps every `IN (...)` list well bounded. */
const PURGE_BATCH = 500;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Archived rows are kept for as long as the plan promises
 * and no longer: the cut-off comes from `retentionDays`, so an enterprise
 * tenant keeps years of history where a free one keeps a month. It is also the
 * lifetime of an archived issue — until then it can be restored, after it the
 * issue is expired and purged here for good.
 *
 * Purging an issue removes it together with its label links, comments and
 * attachments, drops their search documents and gives the attachments' storage
 * back to the usage counter. The audit rows past the window are purged too.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(now, retentionDays);

      try {
        result.processed += await purgeExpiredIssues(orgId, cutoff);
      } catch (error) {
        result.failed += 1;
        logger.error("issue purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

/**
 * Purges every expired issue of one workspace, batch by batch, and returns how
 * many were removed. Search documents go first: they are idempotent to delete,
 * whereas once the rows are gone nothing could find the documents again.
 */
async function purgeExpiredIssues(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<number> {
  let purgedTotal = 0;

  for (;;) {
    const batch = await issueRepo.listExpiredIssues(orgId, cutoff, PURGE_BATCH);
    if (batch.length === 0) break;

    const issueIds = batch.map((issue) => issue.id);
    const commentIds = await commentRepo.listCommentIdsForIssues(
      orgId,
      issueIds,
    );

    await searchRepo.deleteSearchDocuments(orgId, "issue", issueIds);
    await searchRepo.deleteSearchDocuments(orgId, "comment", commentIds);

    const purged = await issueRepo.purgeIssues(orgId, issueIds);
    if (purged.storageMb > 0) {
      await usageRepo.incrementUsage(orgId, {
        storageMbUsed: -purged.storageMb,
      });
    }

    purgedTotal += purged.issues;
    if (purged.issues === 0) break;
  }

  return purgedTotal;
}
