vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issues } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { registerSearchListeners } from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { toIsoTimestamp } from "@/types/common";
import { eq } from "drizzle-orm";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let tenant: Tenant;
let free: Tenant;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("restore", "growth");
  free = await createTenant("restorefree", "free");
  detachers.push(
    registerUsageListeners(),
    registerSearchListeners(),
    registerActivityListeners(),
  );
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

async function archived(
  target: Tenant,
  title: string,
  ageMs = 0,
): Promise<Issue> {
  const issue = await issueService.createIssue(
    target.actors.member,
    issueInput(target.org.id, target.project.id, { title }),
  );
  await issueService.archiveIssue(target.actors.member, target.org.id, issue.id);
  if (ageMs > 0) setArchivedAt(issue.id, new Date(Date.now() - ageMs));
  return (await issueRepo.findIssueById(target.org.id, issue.id)) as Issue;
}

function setArchivedAt(issueId: IssueId, at: Date): void {
  getDb()
    .update(issues)
    .set({ archivedAt: toIsoTimestamp(at) })
    .where(eq(issues.id, issueId))
    .run();
}

function captureRestored(): { seen: unknown[]; off: Unsubscribe } {
  const seen: unknown[] = [];
  const off = subscribe("issue.restored", (payload) => {
    seen.push(payload);
  });
  return { seen, off };
}

describe("restoreIssue guards", () => {
  it("rejects an org outside the actor's organization", async () => {
    const issue = await archived(tenant, "Wrong org");
    await expect(
      issueService.restoreIssue(tenant.actors.member, free.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("throws NotFoundError for an unknown issue", async () => {
    await expect(
      issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        "01ZZZZZZZZZZZZZZZZZZZZZZZZ" as IssueId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("needs the issue:archive permission", async () => {
    const issue = await archived(tenant, "Viewer cannot restore");
    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("lets the assignee restore whatever their role", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Assigned to a viewer",
        assigneeId: tenant.userIds.viewer,
      }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const restored = await issueService.restoreIssue(
      tenant.actors.viewer,
      tenant.org.id,
      issue.id,
    );
    expect(restored.archivedAt).toBeNull();
  });

  it("checks permission before any refusal", async () => {
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Live, viewer asks" }),
    );
    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, live.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });
});

describe("restoreIssue success", () => {
  it("makes the issue live again with its number and publishes issue.restored", async () => {
    const issue = await archived(tenant, "Come back searchable");
    const before = await usageRepo.getUsage(tenant.org.id);
    const { seen, off } = captureRestored();

    try {
      const restored = await issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        issue.id,
      );

      expect(restored.archivedAt).toBeNull();
      expect(restored.number).toBe(issue.number);
      expect(seen).toHaveLength(1);
      expect(seen[0]).toMatchObject({
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        issueId: issue.id,
        projectId: issue.projectId,
      });
    } finally {
      off();
    }

    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed + 1);

    const hits = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "Come back searchable",
      kinds: [],
      limit: 10,
      cursor: null,
    } as never);
    expect(hits.items.map((row) => row.subjectId)).toContain(issue.id);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "issue",
      issue.id,
    );
    expect(audit.map((event) => event.action)).toContain("issue.restored");
  });

  it("accepts an issue archived just under retentionDays × 24h ago", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
    const issue = await archived(free, "Nearly expired");
    setArchivedAt(issue.id, new Date(Date.now() - (30 * MS_PER_DAY - 1)));

    const restored = await issueService.restoreIssue(
      free.actors.member,
      free.org.id,
      issue.id,
    );
    expect(restored.archivedAt).toBeNull();
  });
});

describe("restoreIssue refusals", () => {
  async function refusal(promise: Promise<unknown>): Promise<RestoreRefusedError> {
    const error = await promise.then(
      () => null,
      (thrown: unknown) => thrown,
    );
    expect(error).toBeInstanceOf(RestoreRefusedError);
    return error as RestoreRefusedError;
  }

  it("refuses a live issue as not_archived", async () => {
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Never archived" }),
    );
    const error = await refusal(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id),
    );
    expect(error.reason).toBe("not_archived");
    expect(error.code).toBe("conflict");
  });

  it("refuses an issue archived exactly retentionDays × 24h ago as expired", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
    const issue = await archived(free, "Just expired");
    setArchivedAt(issue.id, new Date(Date.now() - 30 * MS_PER_DAY));

    const { seen, off } = captureRestored();
    try {
      const error = await refusal(
        issueService.restoreIssue(free.actors.member, free.org.id, issue.id),
      );
      expect(error.reason).toBe("expired");
      expect(seen).toHaveLength(0);
    } finally {
      off();
    }

    const still = await issueRepo.findIssueById(free.org.id, issue.id);
    expect(still?.archivedAt).not.toBeNull();
  });

  it("refuses when the project is archived", async () => {
    const issue = await archived(tenant, "Orphaned by its project");
    const { projects } = await import("@/server/db");
    getDb()
      .update(projects)
      .set({ archivedAt: toIsoTimestamp(new Date()) })
      .where(eq(projects.id, tenant.project.id))
      .run();

    try {
      const error = await refusal(
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      );
      expect(error.reason).toBe("project_archived");
    } finally {
      getDb()
        .update(projects)
        .set({ archivedAt: null })
        .where(eq(projects.id, tenant.project.id))
        .run();
    }
  });

  it("refuses when the project is at its per-project quota", async () => {
    const quota = await createTenant("restorequota", "free");
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(quota.org.id, quota.project.id, { title: `Seed ${number}` }),
        quota.actors.member.userId,
        number,
      );
    }
    const target = await issueRepo.findIssueByNumber(
      quota.org.id,
      quota.project.id,
      100,
    );
    await issueService.archiveIssue(
      quota.actors.member,
      quota.org.id,
      target?.id as IssueId,
    );
    // Someone fills the freed slot, so restoring would make 101.
    await issueRepo.insertIssue(
      issueInput(quota.org.id, quota.project.id, { title: "Slot taker" }),
      quota.actors.member.userId,
      101,
    );

    const { seen, off } = captureRestored();
    try {
      const error = await refusal(
        issueService.restoreIssue(
          quota.actors.member,
          quota.org.id,
          target?.id as IssueId,
        ),
      );
      expect(error.reason).toBe("quota");
      expect(seen).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("maps to the conflict code", async () => {
    const live = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mapped refusal" }),
    );
    const error = await refusal(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, live.id),
    );
    expect(toAppError(error)).toMatchObject({
      code: "conflict",
      meta: { reason: "not_archived" },
    });
  });
});
