/**
 * The retention sweep: expired issues are purged for good, with everything
 * that hangs off them, and their numbers are never handed out again.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { and, eq, inArray } from "drizzle-orm";
import {
  activityEvents,
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  searchIndex,
} from "@/server/db";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IssueId, LabelId, ProjectId } from "@/types/common";
import type { Issue } from "@/types/issue";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const MB = 1024 * 1024;
const NOW = new Date("2026-06-01T12:00:00.000Z");
/** Free plan: retentionDays = 30. */
const RETENTION_MS = 30 * MS_PER_DAY;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function archiveAt(issueId: IssueId, at: Date): void {
  getDb()
    .update(issues)
    .set({ archivedAt: toIsoTimestamp(at) })
    .where(eq(issues.id, issueId))
    .run();
}

async function seedIssue(
  tenant: Tenant,
  projectId: ProjectId,
  number: number,
  archivedAt: Date | null,
  labelIds: LabelId[] = [],
): Promise<Issue> {
  const issue = await issueRepo.insertIssue(
    { ...issueInput(tenant.org.id, projectId, { title: `Issue ${number}` }), labelIds },
    tenant.userIds.member,
    number,
  );
  if (archivedAt !== null) archiveAt(issue.id, archivedAt);
  await searchRepo.upsertSearchDocument(
    tenant.org.id,
    "issue",
    issue.id,
    `Issue ${number}`,
    projectId,
  );
  return issue;
}

async function indexed(tenant: Tenant, kind: "issue" | "comment", id: string) {
  const rows = getDb()
    .select()
    .from(searchIndex)
    .where(
      and(
        eq(searchIndex.orgId, tenant.org.id),
        eq(searchIndex.subjectKind, kind),
        eq(searchIndex.subjectId, id),
      ),
    )
    .all();
  return rows.length;
}

describe("runCleanupArchivedJob", () => {
  it("purges every expired issue with its comments, links, attachments and search documents", async () => {
    const tenant = await createTenant("sweep", "free");
    const second = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ff0000",
      description: null,
    });

    const expiredAt = new Date(NOW.getTime() - RETENTION_MS);
    const justInside = new Date(NOW.getTime() - RETENTION_MS + 1);

    // More expired issues than one page or batch would hold, in two projects.
    const expired: Issue[] = [];
    for (let n = 1; n <= 260; n += 1) {
      expired.push(await seedIssue(tenant, tenant.project.id, n, expiredAt, [label.id]));
    }
    for (let n = 1; n <= 240; n += 1) {
      expired.push(await seedIssue(tenant, second.id, n, expiredAt));
    }
    const kept = await seedIssue(tenant, tenant.project.id, 261, justInside);
    const live = await seedIssue(tenant, tenant.project.id, 262, null);

    // Comments (one archived) and attachments on an expired issue and on a kept one.
    const target = expired[0] as Issue;
    const commentIds: CommentId[] = [];
    for (const body of ["first", "second"]) {
      const comment = await commentRepo.insertComment(
        {
          orgId: tenant.org.id,
          issueId: target.id,
          body,
          parentId: null,
          mentionedUserIds: [],
        },
        tenant.userIds.member,
      );
      commentIds.push(comment.id);
      await searchRepo.upsertSearchDocument(tenant.org.id, "comment", comment.id, body, null);
    }
    await commentRepo.archiveComment(tenant.org.id, commentIds[1] as CommentId);
    const keptComment = await commentRepo.insertComment(
      {
        orgId: tenant.org.id,
        issueId: kept.id,
        body: "kept",
        parentId: null,
        mentionedUserIds: [],
      },
      tenant.userIds.member,
    );

    for (const [issue, sizeBytes] of [
      [target, MB + 1], // counts as 2 MB
      [target, 3 * MB], // 3 MB
      [expired[300] as Issue, 1], // 1 MB
      [kept, 4 * MB], // 4 MB, stays
    ] as const) {
      await attachmentRepo.insertAttachment(
        {
          orgId: tenant.org.id,
          issueId: issue.id,
          filename: "f.bin",
          contentType: "application/octet-stream",
          sizeBytes,
        },
        tenant.userIds.member,
      );
    }
    await usageRepo.recomputeUsage(tenant.org.id);
    await usageRepo.incrementUsage(tenant.org.id, { storageMbUsed: 2 + 3 + 1 + 4 - 9 });
    // Counters as the write path would have left them: per-attachment rounding.
    const before = await usageRepo.getUsage(tenant.org.id);
    expect(before.storageMbUsed).toBe(10);
    expect(before.issuesUsed).toBe(2);

    const result = await runCleanupArchivedJob(NOW);
    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(500);

    const expiredIds = expired.map((issue) => issue.id);
    const db = getDb();
    for (let at = 0; at < expiredIds.length; at += 200) {
      const chunk = expiredIds.slice(at, at + 200);
      expect(db.select().from(issues).where(inArray(issues.id, chunk)).all()).toHaveLength(0);
      expect(db.select().from(issueLabels).where(inArray(issueLabels.issueId, chunk)).all()).toHaveLength(0);
      expect(db.select().from(attachments).where(inArray(attachments.issueId, chunk)).all()).toHaveLength(0);
      expect(db.select().from(comments).where(inArray(comments.issueId, chunk)).all()).toHaveLength(0);
      expect(
        db.select().from(searchIndex).where(inArray(searchIndex.subjectId, chunk)).all(),
      ).toHaveLength(0);
    }
    for (const id of commentIds) expect(await indexed(tenant, "comment", id)).toBe(0);

    // Not yet expired, and live, rows are untouched — with their own dependents.
    expect(await issueRepo.findIssueById(tenant.org.id, kept.id)).not.toBeNull();
    expect(await issueRepo.findIssueById(tenant.org.id, live.id)).not.toBeNull();
    expect(await indexed(tenant, "issue", kept.id)).toBe(1);
    expect(await commentRepo.findCommentById(tenant.org.id, keptComment.id)).not.toBeNull();
    expect(await attachmentRepo.listAttachments(tenant.org.id, kept.id)).toHaveLength(1);

    // Storage: dropped by 2 + 3 + 1, so it agrees with a full recount here.
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.storageMbUsed).toBe(4);
    expect(after.issuesUsed).toBe(before.issuesUsed);
    const recount = await usageRepo.recomputeUsage(tenant.org.id);
    expect(recount.storageMbUsed).toBe(after.storageMbUsed);

    // Numbers are never reused, even when the purged issue held the maximum.
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, second.id),
    ).resolves.toBe(241);
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(263);

    // Restoring a purged issue is a plain not-found.
    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, target.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    // A second sweep has nothing left to do.
    const again = await runCleanupArchivedJob(NOW);
    expect(again.failed).toBe(0);
  });

  it("keeps handing out numbers after the highest purged one", async () => {
    const tenant = await createTenant("sweepnumbers", "free");
    await usageRepo.recomputeUsage(tenant.org.id);

    const first = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One" }),
    );
    const top = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Two" }),
    );
    expect([first.number, top.number]).toEqual([1, 2]);

    archiveAt(top.id, new Date(NOW.getTime() - RETENTION_MS - MS_PER_DAY));
    await runCleanupArchivedJob(NOW);

    const next = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Three" }),
    );
    expect(next.number).toBe(3);
  });

  it("uses each workspace's own plan window", async () => {
    const free = await createTenant("sweepplanfree", "free");
    const growth = await createTenant("sweepplangrowth", "growth");
    await usageRepo.recomputeUsage(free.org.id);
    await usageRepo.recomputeUsage(growth.org.id);

    const archivedAt = new Date(NOW.getTime() - 60 * MS_PER_DAY);
    const a = await seedIssue(free, free.project.id, 1, archivedAt);
    const b = await seedIssue(growth, growth.project.id, 1, archivedAt);

    await runCleanupArchivedJob(NOW);

    expect(await issueRepo.findIssueById(free.org.id, a.id)).toBeNull();
    expect(await issueRepo.findIssueById(growth.org.id, b.id)).not.toBeNull();
  });

  it("still purges the audit log past the window", async () => {
    const tenant = await createTenant("sweepaudit", "free");
    await usageRepo.recomputeUsage(tenant.org.id);

    const old = toIsoTimestamp(new Date(NOW.getTime() - RETENTION_MS - MS_PER_DAY));
    const recent = toIsoTimestamp(new Date(NOW.getTime() - MS_PER_DAY));
    for (const occurredAt of [old, recent]) {
      await activityRepo.insertActivity({
        orgId: tenant.org.id,
        action: "issue.created",
        actorId: null,
        subjectKind: "issue",
        subjectId: "x",
        projectId: null,
        summary: "s",
        metadata: {},
        occurredAt,
      });
    }

    await runCleanupArchivedJob(NOW);

    const rows = getDb()
      .select()
      .from(activityEvents)
      .where(eq(activityEvents.orgId, tenant.org.id))
      .all();
    expect(rows.map((row) => row.occurredAt)).toEqual([recent]);
  });
});
